"""netops_server.py - a read-mostly MCP server for IOS XE routers."""
import json
import logging
import os
import re
from urllib.parse import quote

import requests
from mcp.server.fastmcp import FastMCP

logging.basicConfig(level=logging.INFO)          # logs go to stderr, never stdout
log = logging.getLogger("netops")

mcp = FastMCP("netops")

INVENTORY = {"edge-rtr1": "192.0.2.11", "edge-rtr2": "192.0.2.12"}
IFACE_RE = re.compile(r"^(GigabitEthernet|TenGigabitEthernet|Loopback)\d+(/\d+){0,2}$")
HEADERS = {"Accept": "application/yang-data+json",
           "Content-Type": "application/yang-data+json"}


def _check(hostname, interface):
    if hostname not in INVENTORY:
        raise ValueError(f"unknown device {hostname!r}; call list_devices first")
    if not IFACE_RE.match(interface):
        raise ValueError("interface must be a full name such as GigabitEthernet0/0/1")


def _restconf(method, hostname, path, body=None):
    resp = requests.request(
        method, f"https://{INVENTORY[hostname]}/restconf/data/{path}",
        headers=HEADERS, json=body, timeout=10,
        auth=(os.environ["NETOPS_USER"], os.environ["NETOPS_PASS"]),
        verify=os.environ.get("NETOPS_CA_BUNDLE", True),
    )
    resp.raise_for_status()
    return resp.json() if resp.content else {}


@mcp.resource("inventory://devices")
def inventory() -> str:
    """The devices this server is allowed to reach."""
    return json.dumps(INVENTORY)


@mcp.tool()
def list_devices() -> list[str]:
    """List the hostnames this server can query."""
    return sorted(INVENTORY)


@mcp.tool()
def get_interface_status(hostname: str, interface: str) -> dict:
    """Return the admin status, oper status and input errors of one interface.

    hostname: a name returned by list_devices, for example edge-rtr1
    interface: the full IOS XE name, for example GigabitEthernet0/0/1
    """
    _check(hostname, interface)
    path = f"ietf-interfaces:interfaces-state/interface={quote(interface, safe='')}"
    data = _restconf("GET", hostname, path)["ietf-interfaces:interface"]
    return {"interface": data["name"],
            "admin_status": data["admin-status"],
            "oper_status": data["oper-status"],
            "in_errors": int(data["statistics"]["in-errors"])}


@mcp.tool()
def set_interface_description(hostname: str, interface: str,
                              description: str, dry_run: bool = True) -> dict:
    """Set an interface description. Defaults to a dry run that changes nothing."""
    _check(hostname, interface)
    if not re.fullmatch(r"[\w .:/-]{1,80}", description):
        raise ValueError("description: 1-80 letters, digits, spaces or . : / - _")
    path = f"ietf-interfaces:interfaces/interface={quote(interface, safe='')}"
    body = {"ietf-interfaces:interface": {"name": interface,
                                          "description": description}}
    if dry_run:
        return {"dry_run": True, "would_patch": path, "body": body}
    _restconf("PATCH", hostname, path, body)
    log.info("description changed on %s %s", hostname, interface)
    return {"dry_run": False, "changed": True}


@mcp.prompt()
def troubleshoot_interface(hostname: str, interface: str) -> str:
    """A reusable, read-only troubleshooting prompt."""
    return (f"Check {interface} on {hostname} with get_interface_status. "
            "Report admin status, oper status and input errors. Change nothing.")


if __name__ == "__main__":
    mcp.run()                     # stdio transport by default

